def count_element_freq(mixed_tuple):
    # Initialize an empty dictionary to store frequency
    freq_dict = {}
    # Iterate through each item in the tuple
    for item in mixed_tuple:
        # If the item is a tuple itself, recursively count frequencies within it
        if isinstance(item, tuple):
            item_freq = count_element_freq(item)
            # Update or add the frequencies of items in the current tuple to the frequency dictionary
            for key, value in item_freq.items():
                if key in freq_dict:
                    freq_dict[key] += value
                else:
                    freq_dict[key] = value
        # If the item is not a tuple, increment its count in the frequency dictionary
        else:
            if item in freq_dict:
                freq_dict[item] += 1
            else:
                freq_dict[item] = 1
    return freq_dict
```

