    elif x1 > d1 and x2 > d2:
        y1 = max(x1,x2)
        y2 = d1
        # Return the maximum start and intermediate end points between the two ranges
        return (y1,y2)
    elif x1 < d1 and x2 < d2:
        y1 = max(d1,x2)
        y2 = min(d1,x1)
        # Return the intermediate start and minimum end points between the two ranges
        return (d1,y2)
