    free_keys = {}
    # Create another dictionary to store unique keys for each value
    unique_keys = {}

    # Iterate over the pairs list
    for pair in pairs_list:
        first_value = pair[0]
        second_value = pair[1]

        # Check if the first value is an integer
        if type(first_value) == int:
            # If the first value is already in the dictionary, increment its count
            if first_value in free_keys:
                free_keys[first_value] += 1
            # If the first value is not in the dictionary, add it with a count of 1
            else:
                free_keys[first_value] = 1

        # Check if the second value is an integer
        if type(second_value) == int:
            # If the second value is already in the dictionary, increment its count
            if second_value in free_keys:
                free_keys[second_value] += 1
            # If the second value is not in the dictionary, add it with a count of 1
            else:
                free_keys[second_value] = 1

    # Iterate over the keys of the dictionary
    for key in free_keys.keys():
        # If the key has a count of 1, it is a unique key
        if free_keys[key] == 1:
            # Add the key to the unique keys dictionary with its value as 1
            unique_keys[key] = 1

