def second_frequent(seq):
    # Count the frequency of each string in the sequence
    freq = {}
    for word in seq:
        if word in freq:
            freq[word] += 1
        else:
            freq[word] = 1

    # Find the maximum frequency
    max_freq = max(freq.values())

    # Filter the strings that have the maximum frequency
    max_freq_words = [word for word, count in freq.items() if count == max_freq]

    # Find the second most frequent word
    if len(max_freq_words) > 1:
        return max_freq_words[1]
    else:
        return None  # Return None if there are less than two unique words
