        # If i divides n, count its occurrence
        while n % i == 0:
            if i in frequency:
                frequency[i] += 1
            else:
                frequency[i] = 1
            n = n // i
    # If n is a prime number greater than 2
    if n > 2:
        if n in frequency:
            frequency[n] += 1
        else:
            frequency[n] = 1
    # Return the number of distinct prime factor powers
