    pairs.sort(key=lambda x: x.first)

    # Initialize a list to store the maximum chain length at each index
    max_lengths = [1] * n

    # Iterate through each pair starting from the second pair
    for i in range(1, n):
        for j in range(i):
            # If the current pair's first element is greater than the previous pair's second element, update the maximum length
            if pairs[i].first > pairs[j].second and max_lengths[i] < max_lengths[j] + 1:
                max_lengths[i] = max_lengths[j] + 1

    # The maximum length of the longest chain is found at the last element in the max_lengths list
    return max_lengths[-1]
