class Pair(Tuple[int, int]):
    def __init__(self, first: int, second: int):
        super().__init__((first, second))

def max_chain_length(elements: List[Pair], index: int) -> int:
    if index == len(elements):
        return 0

    max_length = 0
    for i in range(index, len(elements)):
        if elements[i].first >= elements[index].second:
            max_length = max(max_length, 1 + max_chain_length(elements, i + 1))
    return max_length
