    if n < 2:
        return 0  # No prime divisors for numbers less than 2

    prime_sum = 0
    # Check for each number from 2 to the square root of n
    for i in range(2, int(n**0.5) + 1):
        # If i is a divisor of n, it's a prime divisor
        if n % i == 0:
            prime_sum += i
            while n % i == 0:
