    map_s_to_t = {}
    map_t_to_s = {}

    # Iterate through the characters of both strings
    for char_s, char_t in zip(s, t):
        # If the character from s is mapped to a different character in t, they are not isomorphic
        if char_s in map_s_to_t and map_s_to_t[char_s] != char_t:
            return False
        # If the character from t is mapped to a different character in s, they are not isomorphic
        if char_t in map_t_to_s and map_t_to_s[char_t] != char_s:
            return False
        # Map both characters
        map_s_to_t[char_s] = char_t
        map_t_to_s[char_t] = char_s

    # If all characters are mapped correctly, they are isomorphic
    return True
