import heapq
def maximum_product(array) :
    heap = [] # To store the top three numbers easily

    # Populate the heap with the top three numbers in the array
    for num in array:
        if len(heap) < 3:
            heapq.heappush(heap, num)
        else:
            heapq.heappushpop(heap, num)

    if len(heap) < 3:
        return -1 # If there are less than 3 elements, return -1

    # Multiply the top three numbers (the largest three) to get the maximum product
    product = heapq.heappop(heap) * heapq.heappop(heap) * heapq.heappop(heap)
    return product
