                lis[i] = lis[j] + 1

    # Build the LDS array
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] > arr[j] and LDS[i] < LDS[j] + 1:
                LDS[i] = LDS[j] + 1

    # The length of the longest bitonic subsequence is the maximum value in the lis and LDS arrays
    return max(lis[i] + LDS[i] - 1 for i in range(n))
