    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                up[i] = max(up[i], up[j] + 1)
                max_length = max(max_length, up[i])

    # Find Longest Decreasing Subsequence (LDS) from right to left
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                down[i] = max(down[i], down[j] + 1)
                max_length = max(max_length, down[i])

    # The length of the longest bitonic subsequence is the max of LIS and LDS at each position
    for i in range(n):
