    # If total is less than or equal to the sum of coins, no need to make transactions
    if total <= sum(coins):
        return total // min(coins)
    else:
        # Initialize the minimum number of transactions with total value
        min_trans = total
        # Iterate through all possible coin combinations
        for i in range(1, total + 1):
            for j in range(len(coins)):
                if i >= coins[j]:
                    # If current coin value is less than or equal to i, update minimum transactions
