    elif cmax == r:
        h = (60 * ((g - b) / delta)) % 360
    elif cmax == g:
        h = (60 * ((b - r) / delta) + 120) % 360
    else:
        h = (60 * ((r - g) / delta) + 240) % 360
    if cmax == 0:
        s = 0
    else:
        s = (delta / cmax) * 100
    v = cmax * 100
    return (h, s, v)
