    if n < 2 or k > n:
        return 0

    # Initialize the base cases
    if n == 1 or n == 2:
        return 1

    # Initialize the memoization array
    memo = [0] * (n + 1)
    memo[1] = memo[2] = 1

    # Fill the memoization array
    for i in range(3, n + 1):
        memo[i] = memo[i - 1] * (n - i + 1) // i

    # The n-th rencontres number is the sum of the k-th row in Pascal's triangle
    return sum(memo[i] for i in range(k) if i + k < n)
```

