def subset(nums, n):
    # Base case: if n is 0, only an empty subset is possible
    if n == 0:
        return 1

    # If n is negative, it's impossible to have non-empty subsets
    if n < 0:
        return 0

    # Recursive case: either include the current number in the subset or exclude it
    return subset(nums, n-1) + subset(nums[:-1], n-1)
