def subset(arr, n):
    # Sort the array
    arr.sort()
    // Initialize the count of subsets
    count = 0
    // Iterates through the array to count the number of subsets
    for i in range(n):
        // Check if the current element is not the same as the previous element
        if i == 0 or arr[i] != arr[i-1]:
            // Initialize the current count for the current subset
            current_count = 1
            // Iterates through the array starting from the next element
            for j in range(i + 1, n):
                # Check if the current element is different from the previous element in the subset
                if arr[j] != arr[j - 1]:
                    // Increment the current count
                    current_count += 1
            // Add the current count to the total count of subsets
            count += current_count
    // Return the total count of subsets
    return count

