import heapq

def nth_super_ugly_number(n, primes):
    seen={1}
    heap = [p for p in primes]
    ugly_nums = []

    while len(ugly_nums) < n:
        next_ugly = heapq.heappop(heap)
        ugly_nums.append(next_ugly)
        for prime in primes:
            if next_ugly * prime not in seen:
                heapq.heappush(heap, next_ugly * prime)
                seen.add(next_ugly * prime)

    return ugly_nums[-1]
