        return "Isosceles Triangle"
    # Check if the sides satisfy the triangle inequality theorem
    elif a + b > c and b + c > a and a + c > b:
        if a**2 + b**2 > c**2 or a**2 + c**2 > b**2 or b**2 + c**2 > a**2:
