    arr.sort()
    left, right = 0, len(arr) - 1
    while left < right:
        if arr[left] + arr[right] == target:
            # Count the same pairs only once
            if left != right and arr[left] == arr[right]:
                count += 2
            else:
                count += 1
            left += 1
            right -= 1
        elif arr[left] + arr[right] < target:
            left += 1
        else:
            right -= 1
    return count
