def lcs_of_three(str1, str2, str3, x, y, z):
    # Create a 3D table to store lengths of common subsequences
    dp = [[[0 for _ in range(z+1)] for _ in range(y+1)] for _ in range(x+1)]

    # Build the 3D table
    for i in range(x+1):
        for j in range(y+1):
            for k in range(z+1):
                if i == 0 or j == 0 or k == 0:
                    dp[i][j][k] = 0
                elif str1[i-1] == str2[j-1] == str3[k-1]:
                    dp[i][j][k] = 1 + dp[i-1][j-1][k-1]
                else:
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i][j-1][k], dp[i][j][k-1])

    return dp[x][y][z]
```
