def sum_of_divisors(num):
    # Initialize sum of divisors to 1 (1 is a divisor of every number)
    sum_divisors = 1
    # Loop through possible divisors from 2 to sqrt(num)
    for i in range(2, int(num**0.5) + 1):
        # If i is a divisor of num
        if num % i == 0:
            # Add both i and num/i to the sum if they are not the same
            sum_divisors += i
            if i != num // i:
                sum_divisors += num // i
    # If num is a perfect square, add the square root only once
    if num**0.5 == int(num**0.5):
        sum_divisors += int(num**0.5)
    return sum_divisors

