def find_kth(A, B, M, N, k):
    if M > N:
        A, B, M, N = B, A, N, M  # Swap A and B if M is greater

    i, j = 0, 0

    for _ in range(k - 1):
        if i < M and j < N:
            if A[i] < B[j]:
                i += 1
            else:
                j += 1
        elif i < M:
            i += 1
        else:
            j += 1

    return A[i]

