def roman_to_int(s):
    # Define a dictionary mapping roman numerals to their integer values
    roman_values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }
    # Initialize the result variable
    result = 0
    # Process each character in the string
    for i, char in enumerate(s):
        # Check if the current character is smaller than the next one
        if i + 1 < len(s) and roman_values[char] < roman_values[s[i + 1]]:
            # Subtract its value from the result
            result -= roman_values[char]
        else:
            # Add its value to the result
            result += roman_values[char]
    return result
