```python
def bell_Number(n):
    if n == 0:
        return 1
    if n == 1:
        return 1
    b = [0] * (n + 1)
    b[0] = 1
    b[1] = 1
    for i in range(2, n + 1):
        b[i] = sum(b[j] * math.factorial(i - j) for j in range(i + 1))
    return b[n]
