def min_coins(coins, value, n):
    # If the value is 0, no coins are needed
    if value == 0:
        return 0
    # If the array is empty or the value is less than the smallest coin, it's not possible to make the value
    elif n == 0 or value < coins[0]:
        return float('inf')
    # Otherwise, the problem can be divided into two parts:
    #   1. Using the first coin
    #   2. Not using the first coin
    # The minimum coins required is the minimum of the two parts plus one (for the first coin)
    return min(1 + min_coins(coins, value-coins[0], n), min_coins(coins, value, n-1))
```
