def min_coins(coins, value, n):
    t = [[0 for _ in range(value+1)] for _ in range(n+1)]
    for i in range(n+1):
        for j in range(value+1):
            if j == 0:
                t[i][j] = 0
            elif i == 0:
                t[i][j] = float('inf')
            elif coins[i-1] <= j:
                t[i][j] = min(1 + t[i][j-coins[i-1]], t[i-1][j])
            else:
                t[i][j] = t[i-1][j]
    return t[n][value]
